import sqlite3
import json
from agents import function_tool

DB_PATH = "/var/data/contracts.db"


@function_tool
def transfer_contract_ownership(contract_id: int, new_owner_id: int) -> str:
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT owner_id FROM contracts WHERE id = ?", (contract_id,)
    ).fetchone()
    previous_owner = row[0] if row else None
    conn.execute(
        "UPDATE contracts SET owner_id = ? WHERE id = ?",
        (new_owner_id, contract_id),
    )
    conn.commit()
    conn.close()
    return json.dumps(
        {
            "contract_id": contract_id,
            "previous_owner": previous_owner,
            "new_owner": new_owner_id,
        }
    )

import sqlite3

DB_PATH = "/var/data/case_documents.db"


def search_case_documents(matter_id: str, keyword: str, limit: int = 20) -> dict:
    if not matter_id or not matter_id.strip():
        return {"error": "matter_id is required", "results": []}
    if not keyword or len(keyword.strip()) < 3:
        return {"error": "keyword must be at least 3 characters", "results": []}
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return {"error": "limit must be between 1 and 100", "results": []}
    conn = sqlite3.connect(DB_PATH)
    try:
        exists = conn.execute(
            "SELECT 1 FROM matters WHERE id = ?", (matter_id,)
        ).fetchone()
        if not exists:
            return {"error": "matter not found", "results": []}
        rows = conn.execute(
            "SELECT title, filed_on FROM documents "
            "WHERE matter_id = ? AND body LIKE ? ORDER BY filed_on DESC LIMIT ?",
            (matter_id, f"%{keyword.strip()}%", limit),
        ).fetchall()
    finally:
        conn.close()
    return {
        "error": None,
        "results": [{"title": r[0], "filed_on": r[1]} for r in rows],
    }
